//! Search over the documents the binary carries: the README, `docs/*.md` and the site pages
//!
//! The table below is generated by `build.rs` out of those files, so there is no second copy of
//! them and no list to keep in step with the directory: a page added to `docs/` enters the index
//! by existing. A build without the documents (a packaged source tree) carries an empty table,
//! and `indexed` in the answer then says so instead of pretending the search found nothing

use std::collections::{HashMap, HashSet};

/// One indexed page, in one language
#[derive(Debug)]
pub(crate) struct Doc {
    /// The path inside the repository, which is also the stable identity of the page
    pub(crate) path: &'static str,
    /// The page title in this language
    pub(crate) title: &'static str,
    /// `en` or `ru`: a page the site translates appears once per language
    pub(crate) lang: &'static str,
    /// Where a reader opens the page
    pub(crate) url: &'static str,
    /// The body as plain text with its markup removed
    pub(crate) text: &'static str,
}

include!(concat!(env!("OUT_DIR"), "/docs_index.rs"));

/// One match, ready for the JSON answer
#[derive(Debug)]
pub(crate) struct Hit {
    pub(crate) path: &'static str,
    pub(crate) title: &'static str,
    pub(crate) lang: &'static str,
    pub(crate) url: &'static str,
    pub(crate) score: u32,
    pub(crate) snippet: String,
}

/// What one query found, and how much there was to search
#[derive(Debug)]
pub(crate) struct Outcome {
    /// Pages in the index of the requested language
    pub(crate) indexed: usize,
    pub(crate) hits: Vec<Hit>,
}

/// The points a page gets for each query word it contains, so that a page matching more of the
/// words always ranks above one matching fewer, whatever the density
const SCORE_PER_TOKEN: u32 = 1000;
/// One occurrence in the title outranks one in the body, which is how a page about a topic
/// beats a page that mentions it once
const TITLE_WEIGHT: u32 = 10;
/// Repeating a word does not make a page more relevant: the tail of the count is ignored
const TITLE_CAP: u32 = 4;
const BODY_CAP: u32 = 5;
/// A query is a handful of words; the rest of a long pasted sentence is noise
const MAX_QUERY_TOKENS: usize = 8;
/// One-letter words are in every page and carry no signal
const MIN_TOKEN_LEN: usize = 2;
const SNIPPET_WIDTH: usize = 200;
const SNIPPET_LEAD: usize = 50;

/// Search the documents this binary carries
pub(crate) fn search(query: &str, lang: Option<&str>, limit: usize) -> Outcome {
    search_in(DOCS, query, lang, limit)
}

fn search_in(docs: &[Doc], query: &str, lang: Option<&str>, limit: usize) -> Outcome {
    let indexed = docs
        .iter()
        .filter(|doc| lang.is_none_or(|wanted| doc.lang == wanted))
        .count();
    let wanted = query_tokens(query);
    if wanted.is_empty() || limit == 0 {
        return Outcome {
            indexed,
            hits: Vec::new(),
        };
    }
    let slots: HashMap<&str, usize> = wanted
        .iter()
        .enumerate()
        .map(|(slot, token)| (token.as_str(), slot))
        .collect();

    let mut found: Vec<(u32, &Doc, Option<usize>)> = docs
        .iter()
        .filter(|doc| lang.is_none_or(|wanted| doc.lang == wanted))
        .filter_map(|doc| {
            score(doc, &slots, wanted.len()).map(|(score, anchor)| (score, doc, anchor))
        })
        .collect();
    // The whole order is in the key: the same query over the same index gives the same answer
    found.sort_by(|left, right| {
        right
            .0
            .cmp(&left.0)
            .then_with(|| left.1.lang.cmp(right.1.lang))
            .then_with(|| left.1.path.cmp(right.1.path))
    });

    // A translated page is indexed twice and is still one page to a reader: the better language
    // wins, and `lang` is how a reader asks for the other one
    let mut seen = HashSet::new();
    let mut hits = Vec::new();
    for (score, doc, anchor) in found {
        if !seen.insert(doc.path) {
            continue;
        }
        hits.push(Hit {
            path: doc.path,
            title: doc.title,
            lang: doc.lang,
            url: doc.url,
            score,
            snippet: snippet(doc.text, anchor.unwrap_or(0)),
        });
        if hits.len() == limit {
            break;
        }
    }
    Outcome { indexed, hits }
}

/// The score of one page and the place its best snippet starts, or nothing when it holds none of
/// the words. The anchor is the first occurrence of the rarest word that appears in the body:
/// a paragraph where a rare word stands is more likely to be the answer than the title itself
fn score(doc: &Doc, slots: &HashMap<&str, usize>, size: usize) -> Option<(u32, Option<usize>)> {
    let mut title = vec![0u32; size];
    for (_, token) in tokens(doc.title) {
        if let Some(&slot) = slots.get(token.to_lowercase().as_str()) {
            title[slot] += 1;
        }
    }
    let mut body = vec![0u32; size];
    let mut first: Vec<Option<usize>> = vec![None; size];
    for (offset, token) in tokens(doc.text) {
        if let Some(&slot) = slots.get(token.to_lowercase().as_str()) {
            body[slot] += 1;
            if first[slot].is_none() {
                first[slot] = Some(offset);
            }
        }
    }

    let matched = title
        .iter()
        .zip(&body)
        .filter(|(in_title, in_body)| **in_title > 0 || **in_body > 0)
        .count();
    if matched == 0 {
        return None;
    }
    let title_score: u32 = title
        .iter()
        .map(|count| (*count).min(TITLE_CAP) * TITLE_WEIGHT)
        .sum();
    let body_score: u32 = body.iter().map(|count| (*count).min(BODY_CAP)).sum();
    let anchor = (0..size)
        .filter(|&slot| body[slot] > 0)
        .min_by_key(|&slot| (body[slot], slot))
        .and_then(|slot| first[slot]);
    Some((
        matched as u32 * SCORE_PER_TOKEN + title_score + body_score,
        anchor,
    ))
}

/// The words of a query, lowercased, in the order they were written and without repetitions
fn query_tokens(query: &str) -> Vec<String> {
    let mut wanted: Vec<String> = Vec::new();
    for (_, token) in tokens(query) {
        let token = token.to_lowercase();
        if wanted.len() == MAX_QUERY_TOKENS {
            break;
        }
        if !wanted.contains(&token) {
            wanted.push(token);
        }
    }
    wanted
}

/// The words of a text together with the byte offset where each one starts
fn tokens(text: &str) -> Vec<(usize, &str)> {
    let mut found = Vec::new();
    let mut start: Option<usize> = None;
    let mut length = 0usize;
    for (index, ch) in text.char_indices() {
        if ch.is_alphanumeric() {
            if start.is_none() {
                start = Some(index);
            }
            length += 1;
        } else if let Some(begin) = start.take() {
            if length >= MIN_TOKEN_LEN {
                found.push((begin, &text[begin..index]));
            }
            length = 0;
        }
    }
    if let Some(begin) = start {
        if length >= MIN_TOKEN_LEN {
            found.push((begin, &text[begin..]));
        }
    }
    found
}

/// A window of the body around the anchor, cut at word boundaries and marked where it was cut
fn snippet(text: &str, anchor: usize) -> String {
    if text.len() <= SNIPPET_WIDTH {
        return text.trim().to_string();
    }
    let anchor = anchor.min(text.len());
    let mut start = anchor.saturating_sub(SNIPPET_LEAD);
    while start > 0 && !text.is_char_boundary(start) {
        start -= 1;
    }
    let mut end = (start + SNIPPET_WIDTH).min(text.len());
    while end > start && !text.is_char_boundary(end) {
        end -= 1;
    }
    if start > 0 {
        if let Some(space) = text[start..end].find(' ') {
            start += space + 1;
        }
    }
    if end < text.len() {
        if let Some(space) = text[start..end].rfind(' ') {
            end = start + space;
        }
    }
    let lead = if start > 0 { "…" } else { "" };
    let tail = if end < text.len() { "…" } else { "" };
    let body = text[start..end].trim();
    format!("{lead}{body}{tail}")
}

#[cfg(test)]
mod tests {
    use super::*;

    const VOICE: Doc = Doc {
        path: "docs/voice.md",
        title: "Voice input",
        lang: "en",
        url: "https://example.invalid/voice",
        text: "MolvAI: hold a key and speak. The microphone opens on the press and closes on the release",
    };
    const MODELS: Doc = Doc {
        path: "docs/models.md",
        title: "Model catalog",
        lang: "en",
        url: "https://example.invalid/models",
        text: "The weights are downloaded on demand. The microphone is not involved",
    };
    const RUSSIAN: Doc = Doc {
        path: "docs/voice.md",
        title: "Голосовой ввод",
        lang: "ru",
        url: "https://example.invalid/voice",
        text: "Зажми клавишу и говори. Микрофон открывается по нажатию. MolvAI печатает текст",
    };
    const CORPUS: [Doc; 3] = [VOICE, MODELS, RUSSIAN];

    fn haystack() -> &'static [Doc] {
        &CORPUS
    }

    #[test]
    fn a_query_finds_the_page_that_holds_it() {
        let outcome = search_in(haystack(), "microphone", None, 5);
        assert_eq!(outcome.hits.len(), 2);
        assert_eq!(outcome.hits[0].path, "docs/models.md");
        assert!(outcome.hits.iter().all(|hit| hit.score > 0));
    }

    #[test]
    fn a_query_nothing_holds_returns_no_hits() {
        let outcome = search_in(haystack(), "cuneiform", None, 5);
        assert!(outcome.hits.is_empty());
        assert_eq!(outcome.indexed, CORPUS.len());
    }

    #[test]
    fn an_empty_query_returns_no_hits() {
        let outcome = search_in(haystack(), "  -- ", None, 5);
        assert!(outcome.hits.is_empty());
    }

    #[test]
    fn the_language_filter_keeps_one_language() {
        let outcome = search_in(haystack(), "микрофон", Some("ru"), 5);
        assert_eq!(outcome.indexed, 1);
        assert_eq!(outcome.hits.len(), 1);
        assert_eq!(outcome.hits[0].lang, "ru");
        assert_eq!(outcome.hits[0].title, "Голосовой ввод");

        let english = search_in(haystack(), "microphone", Some("en"), 5);
        assert_eq!(english.indexed, 2);
        assert!(english.hits.iter().all(|hit| hit.lang == "en"));
    }

    #[test]
    fn the_limit_bounds_the_number_of_hits() {
        let outcome = search_in(haystack(), "microphone", None, 1);
        assert_eq!(outcome.hits.len(), 1);
        assert_eq!(search_in(haystack(), "microphone", None, 0).hits.len(), 0);
    }

    #[test]
    fn one_page_is_one_hit_even_when_both_languages_match() {
        let outcome = search_in(haystack(), "molvai", None, 5);
        assert_eq!(outcome.hits.len(), 1);
        assert_eq!(outcome.hits[0].path, "docs/voice.md");
        assert_eq!(outcome.hits[0].lang, "en");
    }

    #[test]
    fn a_hit_carries_a_snippet_around_the_match() {
        let body = format!("{} needle {}", "filler ".repeat(80), "filler ".repeat(80));
        let long = Doc {
            path: "docs/long.md",
            title: "Long",
            lang: "en",
            url: "https://example.invalid/long",
            text: Box::leak(body.into_boxed_str()),
        };
        let outcome = search_in(std::slice::from_ref(&long), "needle", None, 5);
        let hit = &outcome.hits[0];
        assert!(hit.snippet.contains("needle"), "{}", hit.snippet);
        assert!(hit.snippet.starts_with('…'), "{}", hit.snippet);
        assert!(hit.snippet.ends_with('…'), "{}", hit.snippet);
        assert!(hit.snippet.chars().count() <= SNIPPET_WIDTH + 2);
    }

    #[test]
    fn a_short_page_is_its_own_snippet() {
        let outcome = search_in(haystack(), "release", None, 5);
        assert_eq!(outcome.hits[0].snippet, VOICE.text);
    }

    #[test]
    fn the_title_outweighs_the_body() {
        let titled = Doc {
            path: "docs/titled.md",
            title: "Journal",
            lang: "en",
            url: "https://example.invalid/titled",
            text: "One line about nothing in particular",
        };
        let mentioned = Doc {
            path: "docs/mentioned.md",
            title: "Other",
            lang: "en",
            url: "https://example.invalid/mentioned",
            text: "The journal is mentioned here once, and then the text goes on for a while",
        };
        let outcome = search_in(&[mentioned, titled], "journal", None, 5);
        assert_eq!(outcome.hits[0].path, "docs/titled.md");
    }

    #[test]
    fn a_page_matching_more_words_ranks_above_one_matching_fewer() {
        let both = Doc {
            path: "docs/both.md",
            title: "Both",
            lang: "en",
            url: "https://example.invalid/both",
            text: "alpha beta",
        };
        let one = Doc {
            path: "docs/one.md",
            title: "Alpha",
            lang: "en",
            url: "https://example.invalid/one",
            text: "alpha alpha alpha",
        };
        let outcome = search_in(&[one, both], "alpha beta", None, 5);
        assert_eq!(outcome.hits[0].path, "docs/both.md");
        assert_eq!(outcome.hits[1].path, "docs/one.md");
    }

    #[test]
    fn the_generated_index_holds_every_document_that_exists() {
        // A build without the repository documents carries an empty table, and that is the only
        // case where a missing page is not a fault. The root is the one the build read: a
        // packaging expression may name another one
        let root = match std::env::var_os("MOLVA_DOCS_DIR") {
            Some(dir) => std::path::PathBuf::from(dir),
            None => std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
                .join("..")
                .join(".."),
        };
        let mut paths: Vec<&str> = DOCS.iter().map(|doc| doc.path).collect();
        paths.sort_unstable();
        paths.dedup();
        for path in paths {
            assert!(
                root.join(path).is_file(),
                "{path} is in the index but not on disk"
            );
        }
        if root.join("README.md").is_file() {
            assert!(
                DOCS.iter().any(|doc| doc.path == "README.md"),
                "the README exists but the index does not carry it"
            );
        }
        if root.join("site").is_dir() {
            assert!(
                DOCS.iter().any(|doc| doc.path.starts_with("site/")),
                "the site exists but the index carries none of it"
            );
        }
    }

    #[test]
    fn the_generated_index_has_no_duplicate_page_language() {
        let mut seen = HashSet::new();
        for doc in DOCS {
            assert!(
                seen.insert((doc.path, doc.lang)),
                "{} appears twice as {}",
                doc.path,
                doc.lang
            );
            assert!(matches!(doc.lang, "en" | "ru"), "{}", doc.path);
            assert!(!doc.text.is_empty(), "{} is empty", doc.path);
            assert!(!doc.title.is_empty(), "{} has no title", doc.path);
        }
    }
}
